@extends('layouts.app') @section('title',$product->name) @section('content')<div class="detail"><div class="photo large">@if($product->image)<img src="{{ asset('storage/'.$product->image) }}" alt="{{ $product->name }}">@else<span>SN</span>@endif</div><div><p class="eyebrow">{{ $product->category?->name }}</p><h1>{{ $product->name }}</h1><p>{{ $product->description }}</p><h2>{{ number_format((float)$product->price($currency),2) }} {{ $currency }}</h2><p>{{ $product->stock }} disponible(s) · {{ $product->condition==='new'?'Neuf':'Occasion' }}</p><form method="post" action="{{ route('cart.add',$product) }}" class="inline">@csrf<input type="number" name="quantity" value="1" min="1" max="{{ max(1,$product->stock) }}"><button class="btn" @disabled(!$product->stock)>Ajouter au panier</button></form>@auth<form method="post" action="{{ route('favorites.toggle',$product) }}">@csrf<button class="btn secondary">♡ Ajouter aux favoris</button></form>@endauth</div></div><h2>Avis clients</h2>@foreach($product->reviews->where('is_approved',true) as $review)<div class="review"><strong>{{ $review->user->name }} · {{ $review->rating }}/5</strong><p>{{ $review->comment }}</p></div>@endforeach@auth<form method="post" action="{{ route('reviews.store',$product) }}" class="form narrow">@csrf<label>Votre note<select name="rating">@for($i=5;$i>=1;$i--)<option value="{{ $i }}">{{ $i }}/5</option>@endfor</select></label><label>Commentaire<textarea name="comment"></textarea></label><button class="btn">Envoyer l’avis</button></form>@endauth@endsection
